#!/usr/bin/env python3
"""Catch-up sync for rounds 39-44. Your copy missed fix_features_39 and parts of 42/43, so these files are
brought fully up to date. Run from the repo root. Safe to run twice. Any file that is replaced is first copied
to ~/xtrium_backup_45/ (outside the repo)."""
import os, sys, zlib, base64, shutil, hashlib
sys.stdout.reconfigure(errors='replace')
DATA = {"backend/app/api/v1/routes/quality.py": "", "backend/app/services/peer_notes.py": "", "backend/app/services/quality.py": "", "backend/app/services/sop_requirements.py": "", "backend/app/services/source_audit.py": "", "backend/tests/peer_notes/run.py": "", "backend/tests/peer_notes/training_examples.jsonl": "", "backend/tests/sop_contract/run.py": "", "docs/QUALITY_REVIEW_GUIDE.md": "", "docs/TRAINING_SPEC_peer_note_to_field.md": "", "frontend/src/components/enh/PageReader.tsx": "", "frontend/src/components/enh/ReviewSidePanel.tsx": "", "frontend/src/components/enh/ReviewWorkspace.tsx": "", "frontend/src/components/enh/SopRules.tsx": "", "frontend/src/pages/Quality.tsx": ""}
bk = os.path.expanduser("~/xtrium_backup_45")
n = 0
for path, b in DATA.items():
    new = zlib.decompress(base64.b64decode(b))
    if os.path.exists(path):
        old = open(path, 'rb').read()
        crlf = b'\r\n' in old
        if old.replace(b'\r\n', b'\n') == new:
            print("same     ", path); continue
        os.makedirs(os.path.dirname(os.path.join(bk, path)), exist_ok=True)
        shutil.copy2(path, os.path.join(bk, path))
        verb = "replaced "
    else:
        crlf = False; verb = "created  "
        os.makedirs(os.path.dirname(path) or ".", exist_ok=True)
    out = new.replace(b'\n', b'\r\n') if crlf else new
    open(path, 'wb').write(out)
    print(verb, path); n += 1
print()
print(n, "file(s) updated." + (" Backups are in " + bk if n else ""))
